import{_ as a,o as t,c as i,a2 as n}from"./chunks/framework.k9nOhppk.js";const g=JSON.parse('{"title":"Guide","description":"","frontmatter":{"title":"Guide"},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":1791864160000}'),r={name:"guide/index.md"};function s(o,e,d,l,u,h){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="guide" tabindex="-1">Guide <a class="header-anchor" href="#guide" aria-label="Permalink to &quot;Guide&quot;">​</a></h1><p>The guide explains one idea per page: what it is for, how to use it well, and the mistakes it prevents. The <a href="/tutorial/">tutorial</a> walks through the language in order; the <a href="/reference/language/">reference</a> states the exact rules. Every guide&#39;s code is a real program that the test suite runs.</p><h2 id="state-and-waiting" tabindex="-1">State and waiting <a class="header-anchor" href="#state-and-waiting" aria-label="Permalink to &quot;State and waiting&quot;">​</a></h2><ul><li><a href="/guide/entities">Entities</a>: state with one owner, changed one transaction at a time.</li><li><a href="/guide/jobs-and-waiting">Jobs and waiting</a>: durable functions that pause at <code>!</code> steps for as long as they need and survive restarts.</li><li><a href="/guide/views-events-schedules">Views, events and schedules</a>: starting jobs when entities change, when something happens, or at a time of day.</li><li><a href="/guide/testing">Testing with time and recordings</a>: fresh stores, a clock you move, and services replayed from recordings.</li></ul><h2 id="boundaries" tabindex="-1">Boundaries <a class="header-anchor" href="#boundaries" aria-label="Permalink to &quot;Boundaries&quot;">​</a></h2><ul><li><a href="/guide/contracts">Talking to other services</a>: contracts, keys, lost replies, and the wire format.</li><li><a href="/guide/effects">Effects</a>: what a function may touch, stated where it matters.</li><li><a href="/guide/ai-calls">AI calls</a>: asking a model for a typed value.</li></ul><h2 id="shipping" tabindex="-1">Shipping <a class="header-anchor" href="#shipping" aria-label="Permalink to &quot;Shipping&quot;">​</a></h2><ul><li><a href="/guide/running">Running in production</a>: <code>eye run</code>, the journal, <code>eye runs</code>, and configuration.</li><li><a href="/guide/doc-comments">Doc comments</a>: documenting code for people, editors and models.</li></ul><p>The basics (values, mutation, types and matching, errors) are taught by the <a href="/tutorial/">tutorial</a> and specified in the <a href="/reference/language/">language reference</a>.</p>',9)])])}const f=a(r,[["render",s]]);export{g as __pageData,f as default};
